$(document).ready(function() {
	var c = document.createElement("img");
	c.src = "area_publica/jsf/jquery/images/loadingLC.gif";
	var b = $('<div>&nbsp;aguarde...</div>').prepend(c);
	if ($("#formContato").is("form")) {
		
		$("#formContato #divSubmit").prepend(b.hide());
		var a = function() {
			b.ajaxStart(function() {
				$("div.error").hide();
				$("#formContato #divSubmit #divAcao").hide();
				b.show()
			}).ajaxStop(function() {
				b.hide();
				$("#formContato #divSubmit #divAcao").show()
			}).ajaxError(function(j, h, k) {
				b.hide();
				$("#formContato #divSubmit #divAcao").show();
				RM.widgets.status_bar("add_CONTATO_status_bar", "error", RM.lang.ajax_error, RM.lang.ajax_try_again)
			});
			if ($("#cmdContato").val() != "incluirContato") {
				$.redirecionarUrl("index.php?cmd=formContato");
				return false
			}
			
			var form = $("#formContato");
			var recaptcha_site_key = form.data('sitekey');
		
			grecaptcha.ready(function () {
				grecaptcha.execute(recaptcha_site_key, {
					action: 'submit'
				}).then(function (token) {
					var e = $("#formContato").serializeArray();
					var f = {};
					
					f.rmc_jsonapi_version = 2;
					f.rmc_jsonapi_module = "Contato";
					f.rmc_jsonapi_func = "add_contato";
					f.cmd = "incluirContato";

					f['g-recaptcha-response'] = token;	
					for (i in e) {
						f[e[i].name] = e[i].value
					}
					var g = $("#formContato").serialize();
					var d = {
						data: f,
						dataType: "json",
						url: "index.php",
						success: function(j) {
							var h = j;
							if (h.rmcresult.error) {
								RM.widgets.status_bar("add_CONTATO_status_bar", "error", RM.lang.Error, h.rmcresult.error)
							} else {
								if (h.rmcresult.data[0].result.status == "1") {
									RM.widgets.status_bar("add_CONTATO_status_bar", "success", RM.lang.contato_added, RM.lang.Thank_you, {
										showIcons: false
									});
									if(h.rmcresult.data[0].result.redirectUrl.length > 0){
										window.location.href = h.rmcresult.data[0].result.redirectUrl;
									}
									$("#formContato").clearForm()
								} else {
									RM.widgets.status_bar("add_CONTATO_status_bar", "error", RM.lang.Error, h.rmcresult.data[0].result.statusmsg)
								}
							}
						}
						,complete: function(){
							try{
								grecaptcha.reset()
							}catch(err){
		
							}finally{
								b.show();
							}
						}
					};
					$("#formContato").ajaxSubmit(d)
				})
			})
			
		};
		jQuery.validator.messages.required = "";
		jQuery.validator.messages.email = "";
		$("#formContato").validate({
			invalidHandler: function(g, d) {
				var h = d.numberOfInvalids();
				if (h) {
					var f = h == 1 ? "O campo destacado é de preenchimento obrigatório" : "Os " + h + " campos destacados são de preenchimento obrigatório";
					$("div.error span").html(f);
					$("div.error").show()
				} else {
					$("div.error").hide()
				}
			},
			submitHandler: function() {
				if(!$("#concorda").prop('checked') && $("#concorda").val() == 's'){
					alert("Para prosseguir, leia e aceite nossa Política de Privacidade")
				}else{
					a()
				}
			}
		});
		$(".focus").focus()
	}
});